const QUIZ_TITLE = 'European Chidon Tanach 5786 (January 2026)';

// Source images live alongside the TS source (not dist/) so both `tsx` (dev) and the compiled
// build (dist/db -> ../../src/assets) resolve to the same files without a separate copy step.
const CHIDON_PICS_DIR = path.join(__dirname, '..', '..', 'src', 'assets', 'chidon-pics');

type ChoiceSpec = { text: string; isCorrect: boolean; translations?: Translations };
type QuestionSpec = { type: 'single' | 'text'; text: string; translations?: Translations; points: number; choices: ChoiceSpec[]; imageFile?: string };

function tf(text: string, answer: boolean, translations: Translations, trueLabelTranslations: Translations, falseLabelTranslations: Translations): QuestionSpec {
  return {
    type: 'single',
    text,
    translations,
    points: 1,
    choices: [
      { text: 'True', isCorrect: answer === true, translations: trueLabelTranslations },
      { text: 'False', isCorrect: answer === false, translations: falseLabelTranslations },
    ],
  };
}

function mc(text: string, options: string[], correctIndex: number, translations: Translations, optionTranslations: Translations[]): QuestionSpec {
  return {
    type: 'single',
    text,
    translations,
    points: 1,
    choices: options.map((o, i) => ({ text: o, isCorrect: i === correctIndex, translations: optionTranslations[i] })),
  };
}

function open(text: string, translations: Translations, points = 1, imageFile?: string): QuestionSpec {
  return { type: 'text', text, translations, points, choices: [], imageFile };
}

