export function seedChidonQuiz() {
  const existing = db.prepare('SELECT id FROM quizzes WHERE title = ?').get(QUIZ_TITLE);
  if (existing) {
    console.log(`"${QUIZ_TITLE}" already exists, skipping.`);
    return;
  }

  const admin = db.prepare('SELECT id FROM admins ORDER BY id LIMIT 1').get() as { id: number } | undefined;
  if (!admin) {
    console.log('No admin account found yet; skipping Chidon quiz seed.');
    return;
  }

  const seed = db.transaction(() => {
    const quizResult = db
      .prepare('INSERT INTO quizzes (title, description, time_limit_seconds, created_by) VALUES (?, ?, ?, ?)')
      .run(
        QUIZ_TITLE,
        '40 questions across four types: True/False, Multiple Choice, Open Questions, and Picture Questions.',
        3600,
        admin.id,
      );
    const quizId = Number(quizResult.lastInsertRowid);

    const questionColumns = ['quiz_id', 'sort_order', 'type', 'text', ...translationColumns('text'), 'image_path', 'points'];
    const insertQuestion = db.prepare(`INSERT INTO questions (${questionColumns.join(', ')}) VALUES (${questionColumns.map(() => '?').join(', ')})`);
    const choiceColumns = ['question_id', 'text', ...translationColumns('text'), 'is_correct', 'sort_order'];
    const insertChoice = db.prepare(`INSERT INTO choices (${choiceColumns.join(', ')}) VALUES (${choiceColumns.map(() => '?').join(', ')})`);

    const imagePathByFile = new Map<string, string>();
    QUESTIONS.forEach((q, qi) => {
      let imagePath: string | null = null;
      if (q.imageFile) {
        if (!imagePathByFile.has(q.imageFile)) {
          fs.copyFileSync(path.join(CHIDON_PICS_DIR, q.imageFile), path.join(UPLOAD_DIR, q.imageFile));
          imagePathByFile.set(q.imageFile, `/uploads/${q.imageFile}`);
        }
        imagePath = imagePathByFile.get(q.imageFile)!;
      }

      const qResult = insertQuestion.run(
        quizId,
        qi,
        q.type,
        q.text,
        ...translationValues(q.translations ?? {}),
        imagePath,
        q.points,
      );
      const questionId = Number(qResult.lastInsertRowid);
      q.choices.forEach((c, ci) => {
        insertChoice.run(
          questionId,
          c.text,
          ...translationValues(c.translations ?? {}),
          c.isCorrect ? 1 : 0,
          ci,
        );
      });
    });

    return quizId;
  });

  const quizId = seed();
  console.log(`Chidon quiz seeded (id ${quizId}): "${QUIZ_TITLE}" with ${QUESTIONS.length} questions.`);
}
